package com.kurdman.app;
import static org.junit.Assert.*;
import android.app.Application;
import android.graphics.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import java.util.zip.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk={26,34},application=Application.class,qualifiers="en")
public class SavedJobPipelineTest {
    Application app;
    @Before public void setup(){app=RuntimeEnvironment.getApplication();TranslationProjectStore.setCurrent(null);TranslationProjectStore.deleteRecursive(TranslationProjectStore.root(app));app.getSharedPreferences("koorix_projects",0).edit().clear().commit();JobRuntime.init(app);JobRuntime.beginJob();JobRuntime.endJob();Thread.interrupted();}
    @After public void finish(){JobRuntime.endJob();Thread.interrupted();}
    TranslationProject sample(int pages) throws Exception {
        TranslationProject p=TranslationProjectStore.createNew(app,pages>1,"synthetic","synthetic","en");p.resumable=true;p.autoResume=true;p.comicConfig=new ComicTranslationSkill.Config(true,ComicTranslationSkill.Genre.AUTO,"");
        for(int i=0;i<pages;i++){TranslationProject.Page page=new TranslationProject.Page(TranslationProjectStore.pageRelativePath(i+1,".png"),".png");try(OutputStream out=new FileOutputStream(page.sourceFile(p.projectDir))){Bitmap b=Bitmap.createBitmap(12,16,Bitmap.Config.ARGB_8888);b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();}p.pages.add(page);}p.save();return p;
    }
    static class Fake implements SavedJobPipeline.Backend {
        int ocr,translations,renders,failOcr=-1,failTranslation=-1;boolean empty,ocrClosed,translatorClosed;
        public List<Segment> recognize(Bitmap b,TranslationProject p)throws Exception{if(++ocr==failOcr)throw new IOException("Synthetic OCR failure");return empty?new ArrayList<>():new ArrayList<>(Arrays.asList(new Segment("Wait here.",new Rect(1,2,10,14),1)));}
        public void translate(List<Segment> segments,TranslationProject p)throws Exception{if(++translations==failTranslation)throw new IOException("Synthetic translation failure");ComicTranslationSkill.PageResult result=new ComicTranslationSkill.PageResult();for(Segment s:segments)result.results.add(new ComicTranslationSkill.Result("لێرە بوەستە.","synthetic_mock",""));ComicTranslationFlow.apply(segments,result,p.sourceLanguage,p.targetLanguage,p.comicConfig);}
        public ManhwaRenderer.RenderResult render(Bitmap b,TranslationProject p,TranslationProject.Page page){renders++;for(Segment s:page.segments)s.rendered=true;return new ManhwaRenderer.RenderResult(b.copy(Bitmap.Config.ARGB_8888,true),page.segments.size(),0,0,0,page.segments);}
        public void closeOcr(){ocrClosed=true;}public void closeTranslator(){translatorClosed=true;}public void cancel(){}
    }
    SavedJobPipeline.Progress progress=(phase,page,total)->{};
    @Test public void ocrCommitsEachPageAndAReplacementRunnerSkipsIt()throws Exception{TranslationProject p=sample(2);Fake broken=new Fake();broken.failOcr=2;try{SavedJobPipeline.ocr(p,broken,progress);fail();}catch(IOException expected){}assertTrue(broken.ocrClosed);TranslationProject saved=TranslationProject.load(p.projectDir);assertTrue(saved.pages.get(0).ocrComplete);assertFalse(saved.pages.get(1).ocrComplete);Fake next=new Fake();SavedJobPipeline.ocr(saved,next,progress);assertEquals(1,next.ocr);assertEquals("Wait here.",saved.pages.get(0).segments.get(0).text);}
    @Test public void translationRestartPreservesFinishedPageAndGeometry()throws Exception{TranslationProject p=sample(2);Fake first=new Fake();SavedJobPipeline.ocr(p,first,progress);Rect original=new Rect(p.pages.get(0).segments.get(0).box);first.failTranslation=2;try{SavedJobPipeline.translate(p,first,progress);fail();}catch(IOException expected){}assertTrue(first.translatorClosed);TranslationProject saved=TranslationProject.load(p.projectDir);assertTrue(saved.pages.get(0).translationComplete);assertFalse(saved.pages.get(1).translationComplete);Fake next=new Fake();SavedJobPipeline.translate(saved,next,progress);assertEquals(1,next.translations);assertEquals(original,saved.pages.get(0).segments.get(0).box);assertEquals("unreviewed",saved.pages.get(0).segments.get(0).readerReview);}
    @Test public void browserVisiblePagesRunFirstInEachPhaseWithoutChangingChapterOrder()throws Exception{
        TranslationProject p=sample(3);p.privateResults=true;p.pages.get(1).webPriority=true;p.save();
        TranslationProject saved=TranslationProject.load(p.projectDir);assertTrue(saved.pages.get(1).webPriority);
        assertEquals(Arrays.asList(1,0,2),SavedJobPipeline.workOrder(saved));
        List<String> steps=new ArrayList<>();SavedJobPipeline.Progress ordered=(phase,page,total)->steps.add(phase+":"+page);
        Fake backend=new Fake();SavedJobPipeline.ocr(saved,backend,ordered);SavedJobPipeline.translate(saved,backend,ordered);SavedJobPipeline.render(saved,backend,ordered);
        assertEquals(Arrays.asList("0:2","0:1","0:3","1:2","1:1","1:3","2:2","2:1","2:3"),steps);
        assertEquals("pages/0001.png",saved.pages.get(0).sourcePath);assertEquals("pages/0002.png",saved.pages.get(1).sourcePath);
        String before=ProjectResults.binding(saved);saved.pages.get(1).webPriority=false;assertEquals(before,ProjectResults.binding(saved));
        saved.privateResults=false;saved.pages.get(2).webPriority=true;assertEquals(Arrays.asList(0,1,2),SavedJobPipeline.workOrder(saved));
    }
    @Test public void emptyOcrDoesNotCallATranslator()throws Exception{TranslationProject p=sample(1);Fake backend=new Fake();backend.empty=true;SavedJobPipeline.ocr(p,backend,progress);assertEquals(0,p.totalSegments());assertFalse(SavedJobPipeline.needsTranslation(p));SavedJobPipeline.translate(p,backend,progress);assertEquals(0,backend.translations);}
    @Test public void renderedPageCheckpointIsNotRenderedTwice()throws Exception{TranslationProject p=sample(1);Fake backend=new Fake();SavedJobPipeline.ocr(p,backend,progress);SavedJobPipeline.translate(p,backend,progress);SavedJobPipeline.render(p,backend,progress);assertTrue(p.pages.get(0).layoutPrepared);assertEquals(1,backend.renders);TranslationProject saved=TranslationProject.load(p.projectDir);Fake replacement=new Fake();SavedJobPipeline.render(saved,replacement,progress);assertEquals(0,replacement.renders);assertTrue(SavedJobPipeline.renderedPage(saved,0).isFile());}
    @Test public void missingRenderCacheDoesNotRequireAnotherTranslation()throws Exception{TranslationProject p=sample(1);Fake backend=new Fake();SavedJobPipeline.ocr(p,backend,progress);SavedJobPipeline.translate(p,backend,progress);SavedJobPipeline.render(p,backend,progress);assertTrue(SavedJobPipeline.renderedPage(p,0).delete());Fake next=new Fake();SavedJobPipeline.translate(p,next,progress);SavedJobPipeline.render(p,next,progress);assertEquals(0,next.translations);assertEquals(1,next.renders);}
    @Test public void stopChoiceWinsAcrossProcessStateReset()throws Exception{TranslationProject p=sample(1);TranslationProjectStore.allowRecovery(app,p,true);assertTrue(JobRuntime.tryBeginJob());JobRuntime.activateSavedProject(p);JobRuntime.requestStop();TranslationProjectStore.allowRecovery(app,p,true);JobRuntime.endJob();TranslationProjectStore.setCurrent(null);TranslationProject disk=TranslationProjectStore.load(app);JobRuntime.beginJob();JobRuntime.endJob();assertFalse(TranslationProjectStore.canRecover(app,disk));TranslationProjectStore.allowRecovery(app,disk,true);assertTrue(TranslationProjectStore.canRecover(app,disk));}
    @Test public void cbzKeepsNaturalPageOrderAndCannotEscapeTheProject()throws Exception{File archive=new File(app.getCacheDir(),"natural.cbz");byte[] image;TranslationProject p=sample(1);image=Files.readAllBytes(p.pages.get(0).sourceFile(p.projectDir).toPath());try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(archive))){for(int n:new int[]{10,2}){zip.putNextEntry(new ZipEntry("../folder/page"+n+".png"));zip.write(image);zip.write(n);zip.closeEntry();}}SavedJobInput input=new SavedJobInput(null,archive,new ArrayList<>(),"natural","natural","en","ckb",false,true,false,p.comicConfig,p.jobStyle,null);TranslationProject saved=input.prepare(app);assertEquals(2,saved.pages.size());byte[] first=Files.readAllBytes(saved.pages.get(0).sourceFile(saved.projectDir).toPath());assertEquals(2,first[first.length-1]);assertEquals("pages/0001.png",saved.pages.get(0).sourcePath);}
    @Test public void failedPreparationNeverDeletesAnOlderBook()throws Exception{TranslationProject old=sample(1);File archive=new File(app.getCacheDir(),"empty.cbz");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(archive))){}SavedJobInput input=new SavedJobInput(null,archive,new ArrayList<>(),"bad","bad","en","ckb",false,true,false,old.comicConfig,old.jobStyle,null);try{input.prepare(app);fail();}catch(IOException expected){}assertTrue(old.pages.get(0).sourceFile(old.projectDir).isFile());assertEquals(1,TranslationProjectStore.list(app).size());}
    @Test public void everyOriginalTargetAndBothChineseSourcesAreStillAvailable(){assertEquals(74,TranslationLanguages.TARGETS.length);assertEquals(74,TranslationLanguages.LABELS.length);assertTrue(TranslationLanguages.target("ckb"));assertTrue(TranslationLanguages.target("ku"));assertTrue(TranslationLanguages.target("ar"));assertTrue(TranslationLanguages.source("zh-CN"));assertTrue(TranslationLanguages.source("zh-TW"));assertFalse(TranslationLanguages.target("invalid"));}
    @Test public void subscribingWhileIdleCannotOverrideAnotherSelectedBook()throws Exception{TranslationProject selected=sample(1);java.util.concurrent.atomic.AtomicInteger events=new java.util.concurrent.atomic.AtomicInteger();SavedJobCoordinator.Listener listener=(p,status,running)->events.incrementAndGet();SavedJobCoordinator.addListener(listener);SavedJobCoordinator.removeListener(listener);assertEquals(0,events.get());assertSame(selected,TranslationProjectStore.load(app));}
    @Test public void reviewDeclarationsDoNotInvalidateAnUnchangedRenderedPicture()throws Exception{TranslationProject p=sample(1);Fake backend=new Fake();SavedJobPipeline.ocr(p,backend,progress);SavedJobPipeline.translate(p,backend,progress);String before=ProjectResults.binding(p);Segment s=p.pages.get(0).segments.get(0);s.readerReview="uncertain";s.readerReviewBinding="a reader declaration";s.translationWarnings="ocr_low";assertEquals(before,ProjectResults.binding(p));s.ckb="دەقێکی گۆڕاو";assertNotEquals(before,ProjectResults.binding(p));}
    @Test public void previewDecodingIsBoundedWithoutChangingFullSourceGeometry(){assertEquals(1,BitmapIo.previewSampleSize(800,1200));assertTrue(BitmapIo.previewSampleSize(4000,7000)>1);assertTrue(BitmapIo.previewSampleSize(1000,28000)>1);}
    @Test public void jobDiagnosticsKeepStackAndStatusButNotPrivateProviderText(){IOException original=new IOException("Translation HTTP 429 private dialogue and reader name");Throwable safe=SavedJobCoordinator.safeFailure(original);assertTrue(safe.getMessage().contains("HTTP 429"));assertFalse(safe.getMessage().contains("private dialogue"));assertNull(safe.getCause());assertArrayEquals(original.getStackTrace(),safe.getStackTrace());}
}
